def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v not in (0, 3)]
    hollow_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                hollow_cols.add(c)
    for r, c, v in centers:
        own_arms = {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
        for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                if (rr,cc) != (r,c) and grid[rr][cc] == 3 and (rr,cc) not in own_arms:
                    break
                if grid[rr][cc] != 3:
                    if dr == 0 and cc in hollow_cols:
                        out[rr][cc] = 0
                    else:
                        out[rr][cc] = v
                rr += dr; cc += dc
    # Vertical projections take precedence at crossings.
    for r, c, v in centers:
        for dr in (1,-1):
            rr=r+dr
            while 0 <= rr < h:
                if grid[rr][c] == 3 and (rr,c) not in {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}: break
                if grid[rr][c] != 3: out[rr][c] = v
                rr += dr
    return out
